import type { ReactNode } from "react";
import { House, Settings, Volume2, Wifi } from "lucide-react";
import { expect, fn, userEvent, within } from "storybook/test";
import type { ComponentMeta } from "vibestack/stories";
import { AskGraceButton } from "./AskGraceButton.tsx";
import { susan as susanPhoto } from "./Avatar.meta.tsx";
import type { MailAppProps, MailSummary } from "./MailApp.tsx";
import type { MailContact } from "./MailMessageRow.tsx";
import { Rail, RailButton } from "./Rail.tsx";
import { TabletScreen } from "./TabletScreen.tsx";
import { Toast } from "./Toast.tsx";

const railIcon = { size: 28, strokeWidth: 1.9 };

/** The tablet at 8:56 PM with the rail beside the window, as the prototype's Email references show it. */
export const mailScreen = (story: () => ReactNode) => (
  <TabletScreen>
    <Rail
      battery={75}
      time="8:56"
      period="PM"
      date="Fri, Nov 13"
      aria-label="Tablet"
      status={<RailButton icon={<Wifi {...railIcon} />} label="Wi-Fi" />}
      footer={<RailButton icon={<Settings {...railIcon} />} label="Settings" />}
      ask={<AskGraceButton glow="rest" />}
    >
      <RailButton icon={<House {...railIcon} />} label="Home" />
      <RailButton icon={<Volume2 {...railIcon} />} label="Volume" />
    </Rail>
    {story()}
  </TabletScreen>
);

// Drops the focus a play's last tap leaves, so the story shows the screen at rest as the references do.
export const unfocus = () => (document.activeElement as HTMLElement | null)?.blur();

// The clinic's white cross (prototype `av('clinic')`).
const cross = (
  <svg aria-hidden width="30" height="30" viewBox="0 0 24 24">
    <path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z" fill="currentColor" />
  </svg>
);

// The prototype's PEOPLE.
export const people = {
  susan: { name: "Susan", photo: susanPhoto },
  david: { name: "David", tone: 2 },
  clinic: { name: "Main St Clinic", tone: 1, mark: cross },
  linda: { name: "Linda’s salon", tone: 5 },
  book: { name: "Riverside Book Club", tone: 3 },
  joan: { name: "Joan", tone: 6 },
  security: { name: "Account Security", tone: 4 },
} satisfies Record<string, MailContact>;

// The prototype's X.mail.items.
export const inbox: MailSummary[] = [
  { id: "susan", from: people.susan, subject: "Photos from Lily’s recital", time: "2:15 PM", unread: true, attachment: true },
  { id: "clinic", from: people.clinic, subject: "Reminder: your appointment tomorrow at 10 am", time: "11:02 AM", unread: true, attachment: true },
  { id: "book", from: people.book, subject: "Our book for December", time: "Yesterday" },
  { id: "scam", from: people.security, subject: "Urgent: confirm your password", time: "Yesterday" },
];
const sent: MailSummary[] = [{ id: "s1", from: people.david, subject: "Re: Thanksgiving", time: "Monday" }];

const open = fn();
const folder = fn();
const write = fn();

export const meta: ComponentMeta<MailAppProps> = {
  args: { folder: "inbox", counts: { inbox: 2 }, messages: inbox, onOpen: open, onSelectFolder: folder, onWrite: write, onClose: fn() },
  examples: {
    Sent: { folder: "sent", messages: sent },
    Search: { query: "book", messages: inbox.filter((m) => m.id === "book") },
    "Nothing found": { query: "piano", messages: [] },
    Drafts: { folder: "drafts", messages: [] },
    Trash: { folder: "trash", messages: [{ ...inbox[2], id: "book" }] },
    "Moved to Trash": {
      messages: inbox.slice(0, 3),
      toast: (
        <Toast onUndo={fn()}>
          Moved to Trash
        </Toast>
      ),
    },
  },
  decorator: mailScreen,
  play: {
    Default: async ({ canvasElement }: { canvasElement: HTMLElement }) => {
      const canvas = within(canvasElement);
      await userEvent.click(canvas.getByRole("button", { name: /Riverside Book Club/ }));
      await expect(open).toHaveBeenCalledWith("book");
      await userEvent.click(canvas.getByRole("button", { name: /Sent/ }));
      await expect(folder).toHaveBeenCalledWith("sent");
      await userEvent.click(canvas.getByRole("button", { name: "Write" }));
      await expect(write).toHaveBeenCalled();
      unfocus();
    },
  },
};

// Susan's three photos from Lily's recital and the clinic's form, from the prototype's PHOTO (re-encoded smaller).
export const stagePhoto = "data:image/jpeg;base64,";
export const flowersPhoto = "data:image/jpeg;base64,";
export const programPhoto = "data:image/jpeg;base64,";
